<?php /** @var array $areas @var string $basePath @var string $serviceRadius */ ?><section class="l-page-hero"><p class="l-eyebrow">Where we work</p><h1>Local routes. Reliable service.</h1><p><?= e($serviceRadius?:'Use the areas below to explain regular routes, extended travel, and location requirements.') ?></p></section><section class="l-section l-area-grid"><?php foreach ($areas as $area): ?><article class="l-area"><h2><?= e($area['name']) ?></h2><?php if ($area['zip_codes']): ?><p><strong>ZIP codes:</strong> <?= e($area['zip_codes']) ?></p><?php endif; ?><p><?= e($area['map_copy']) ?></p><p><?= e($area['travel_note']) ?></p></article><?php endforeach; ?><a class="l-btn l-btn-primary" href="<?= e_attr($basePath) ?>/request-estimate">Check my property</a></section>
